package net.flovex.core.network;
import net.flovex.core.FlovexCore;import net.flovex.core.data.Storage;import org.bukkit.Bukkit;import org.bukkit.Location;import org.bukkit.entity.Player;import org.bukkit.event.EventHandler;import org.bukkit.event.Listener;import org.bukkit.event.player.PlayerMoveEvent;import java.io.ByteArrayOutputStream;import java.io.DataOutputStream;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
public final class PortalService implements Listener{
 private final FlovexCore plugin;private final Storage db;private final org.bukkit.configuration.file.FileConfiguration cfg;private final Map<UUID,Long> cooldown=new ConcurrentHashMap<>();private volatile List<Map<String,Object>> cached=List.of();
 public PortalService(FlovexCore p,Storage d,org.bukkit.configuration.file.FileConfiguration c){plugin=p;db=d;cfg=c;reload();}private void reload(){cached=db.rows("SELECT * FROM portals ORDER BY name");}
 public String set(Player p,String name,String server,double radius){if(name.isBlank()||server.isBlank()||radius<1||radius>64)return "Invalid portal name, server or radius.";Location l=p.getLocation();db.update("INSERT INTO portals(name,world,x,y,z,radius,server,creator,created) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(name) DO UPDATE SET world=excluded.world,x=excluded.x,y=excluded.y,z=excluded.z,radius=excluded.radius,server=excluded.server,creator=excluded.creator,created=excluded.created",name.toLowerCase(Locale.ROOT),l.getWorld().getName(),l.getX(),l.getY(),l.getZ(),radius,server,p.getUniqueId().toString(),System.currentTimeMillis());reload();return "Portal "+name+" now connects to "+server+".";}
 public boolean delete(String name){boolean removed=db.update("DELETE FROM portals WHERE name=?",name.toLowerCase(Locale.ROOT))>0;if(removed)reload();return removed;}
 public List<Map<String,Object>> list(){return cached;}
 @EventHandler public void onMove(PlayerMoveEvent e){if(!cfg.getBoolean("enabled",true)||!cfg.getBoolean("portals.enabled",true)||e.getTo()==null)return;if(e.getFrom().getBlockX()==e.getTo().getBlockX()&&e.getFrom().getBlockY()==e.getTo().getBlockY()&&e.getFrom().getBlockZ()==e.getTo().getBlockZ())return;Player p=e.getPlayer();long now=System.currentTimeMillis();if(cooldown.getOrDefault(p.getUniqueId(),0L)>now)return;for(var portal:cached){if(!String.valueOf(portal.get("world")).equals(e.getTo().getWorld().getName()))continue;double x=((Number)portal.get("x")).doubleValue(),y=((Number)portal.get("y")).doubleValue(),z=((Number)portal.get("z")).doubleValue(),radius=((Number)portal.get("radius")).doubleValue();if(e.getTo().distanceSquared(new Location(e.getTo().getWorld(),x,y,z))<=radius*radius){String server=String.valueOf(portal.get("server"));try{ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);out.writeUTF("Connect");out.writeUTF(server);p.sendPluginMessage(plugin,"BungeeCord",bytes.toByteArray());cooldown.put(p.getUniqueId(),now+cfg.getInt("portals.cooldown-seconds",10)*1000L);p.sendMessage(plugin.getMessages().prefix()+"§aConnecting to §f"+server+"§a...");}catch(Exception ex){plugin.getLogger().warning("Portal transfer failed: "+ex.getMessage());}return;}}}
}